def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def ncr(n, r):
    return factorial(n) // (factorial(r) * factorial(n - r))

print(f"5! = {factorial(5)}")
print(f"5C2 = {ncr(5, 2)}")
print(f"10C3 = {ncr(10, 3)}")
